"""CODE-19 — AUDIT.md block for the R6b look-ups and zero-compute results, rendered from the code19 records (nothing retyped): every
number carries the record it comes from, the record's SHA-256 and its UTC. Appends one section to docs/AUDIT.md unless --print.

Usage: python -I code19_audit_block.py --repo <worktree> [--print]
"""
from __future__ import annotations

import argparse
import datetime as dt
import hashlib
import json
import subprocess
import sys
from pathlib import Path


def git(repo: Path, *args: str) -> str:
    return subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, check=True, encoding="utf-8").stdout.strip()


def render(repo: Path) -> str:
    c19 = repo / "reproduction" / "v14_rerun" / "code19"
    recs = {}
    for n in ("a1_rain_leadin", "a2_ib_boundary", "a3_hardware", "a4_emsr773_aois", "b4_albufera", "b5_emilia_south", "b_maps_wet_in_excluded", "lookups", "crete_tier1_diagnostics_baseline"):
        p = c19 / f"{n}.json"
        recs[n] = json.loads(p.read_text(encoding="utf-8"))
        recs[n]["_sha"] = hashlib.sha256(p.read_bytes()).hexdigest()[:16]
    now = dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    head = git(repo, "rev-parse", "--short", "HEAD")
    def tag(n):
        return f"`code19/{n}.json` (sha256 {recs[n]['_sha']}…, {recs[n].get('utc')})"
    L = [f"## CODE-19 ({now}) — R6b look-ups and zero-compute results (HEAD `{head}`; no model run; number freeze v1.4.2 stands)", "",
         "Generated by `reproduction/v14_rerun/scripts/code19_audit_block.py` from the records under `reproduction/v14_rerun/code19/` (each cited with its SHA-256 prefix and UTC). "
         "Scripts: `code19_a1_rain_leadin.py`, `code19_a2_ib_boundary.py`, `code19_a3_hardware.py`, `code19_a4_emsr773_aois.py`, `code19_b45_map_checks.py`, `code19_lookups.py`; "
         "Crete baseline tier-1 diagnostics by `crete_tier1_diagnostics.py --runs crete_baseline` (re-scoring on the frozen output, as stated in C1).", ""]
    # A1
    a1 = recs["a1_rain_leadin"]
    L += [f"### A1 — domain-mean precipitation over the active mask {tag('a1_rain_leadin')}", "",
          f"Definition: {a1['definition']}.", "",
          "| event (run) | active cells | lead-in 7 d ERA5 / raw IMERG (mm) | lead-in coverage | simulated ERA5 / raw IMERG (mm) | max 24 h in lead-in ERA5 / IMERG (mm, start) | AMC 5 d before tstart ERA5 / IMERG | 5 d before event day ERA5 / IMERG |",
          "|---|---|---|---|---|---|---|---|"]
    for e in a1["events"]:
        s = e["sources"]; E, I = s["era5"], s["imerg_raw"]
        def w(src, k, f="total_mm"):
            v = src["windows"][k].get(f) if src.get("present") else None
            return "—" if v is None else (f"{v:.1f}" if isinstance(v, float) else str(v))
        cov = f"ERA5 {E['windows']['leadin_7d']['coverage_fraction'] * 100:.0f} % / IMERG {I['windows']['leadin_7d']['coverage_fraction'] * 100:.0f} %"
        L.append(f"| {e['event']} ({e['run']}) | {e['active_cells']} | {w(E, 'leadin_7d')} / {w(I, 'leadin_7d')} | {cov} | {w(E, 'simulated')} / {w(I, 'simulated')} | "
                 f"{w(E, 'leadin_7d', 'max_24h_total_mm')} ({w(E, 'leadin_7d', 'max_24h_start')}) / {w(I, 'leadin_7d', 'max_24h_total_mm')} ({w(I, 'leadin_7d', 'max_24h_start')}) | "
                 f"{w(E, 'amc_5d_before_tstart')} / {w(I, 'amc_5d_before_tstart')} | {w(E, 'amc_5d_before_event_day')} / {w(I, 'amc_5d_before_event_day')} |")
    st = next(e for e in a1["events"] if e["event"] == "strymonas")
    L += ["", f"Strymonas R4 as configured: infiltration {st['infiltration']}, realised mean CN (active cells) {st['cn_realised_active_mean']}. The rule's clause (docs/frozen_rule_R.md): "
          + " ".join(x.strip() for x in a1["rule_R4_clause"]) + " — the clause does not quantify 'multi-day wet spell'; the numbers above are reported for the author's reading. "
          "Files that do not cover the 7-day lead-in (Mandra 1 d, Valencia 3 d of IMERG) are reported over the covered part; nothing was downloaded.", ""]
    # A2
    a2 = recs["a2_ib_boundary"]
    L += [f"### A2 — inverse-barometer boundary as realised {tag('a2_ib_boundary')}", "", f"Definition: {a2['definition']}.", "",
          "| event (run) | bnd points / msk = 2 cells | realised max zs at the boundary (m, time) | expected IB max from the pressure at the boundary (m, time; p min hPa) | realised / expected | window-mean expected IB (m) | event-mean offset recorded (A2_pavbnd_reference) |",
          "|---|---|---|---|---|---|---|"]
    for e in a2["events"]:
        r = e["reference_record"] or {}
        L.append(f"| {e['event']} ({e['run']}) | {e['bnd_points']} / {e['msk2_cells']} | {e['realised_zs_max_m']:.3f} ({e['realised_zs_max_time']}) | {e['expected_ib_max_m']:.3f} ({e['expected_ib_max_time']}; {e['pressure_min_at_boundary_hpa']}) | "
                 f"{e['realised_over_expected']} | {e['expected_ib_window_mean_m']:+.3f} | {r.get('ib_offset_at_mean_m'):+.3f} |")
    mx = max(a2["events"], key=lambda e: e["realised_zs_max_m"])
    L += ["", f"Largest realised boundary rise: {mx['realised_zs_max_m']:.3f} m, {mx['event']} ({mx['run']}), {mx['realised_zs_max_time']}; bzs files all zero: "
          f"{all(e['bzs_values_all_zero'] for e in a2['events'])}; pavbnd 101325 Pa in every sfincs.inp.", ""]
    # A3
    a3 = recs["a3_hardware"]; cim = a3["machine_cim"]
    pr, co, os_ = cim.get("processor", {}), cim.get("computer", {}), cim.get("os", {})
    L += [f"### A3 — hardware of the canonical runs {tag('a3_hardware')}", "",
          f"- Machine (read on host `{a3['read_on_host']}`): {pr.get('Name')}, {pr.get('NumberOfCores')} physical cores / {pr.get('NumberOfLogicalProcessors')} logical processors, "
          f"{cim.get('installed_memory_bytes', 0) / 2**30:.0f} GiB installed RAM ({co.get('TotalPhysicalMemory', 0) / 2**30:.1f} GiB usable), {os_.get('Caption')} {os_.get('Version')} {os_.get('OSArchitecture')}.",
          "- Every canonical run: sfincs.log `" + a3["runs"][0]["sfincs_build_revision"] + "`, Build-Date " + str(a3["runs"][0]["sfincs_build_date"]) + ", `Using 16 of 16 available threads`; HydroMT and SFINCS invoked from "
          "`C:/Users/dvalsamis/…/sfincs-viz` on `D:/ELKAK/implementation/v14/<run>` — same machine for all six (" + ", ".join(f"{r['run']} {r['start_utc']}→{r['end_utc']}" for r in a3["runs"]) + ").",
          "- Caveat for Table 2 wall-clock times: the run windows overlap (pineios_enhanced_v142 and emilia_enhanced_8aoi_v142 both start 2026-10-20T12:46:27Z; valencia starts when emilia ends), so those timings were measured with two 16-thread runs sharing the CPU.",
          "- Build-Date in the log is 2025-11-18 while the records name the release `mt_Faber_release_2025.02`; the executable folder is `SFINCS_v2.3.0_mt_Faber_release_exe` (manual PDFs dated 2025-11-19) — the '2025.02' suffix is not confirmed by the binary.", ""]
    # A4
    a4 = recs["a4_emsr773_aois"]
    L += [f"### A4 — EMSR773 areas of interest {tag('a4_emsr773_aois')}", "",
          f"- Activation as listed by the EMS dashboard API on {a4['api_fetched_utc']} (snapshot `{a4['snapshot_file']}`, sha256 {a4['snapshot_sha256'][:16]}…): **{a4['n_aois']} AOIs**; "
          f"{a4['m_bbox']} intersect the configured lon/lat bbox, {a4['m_grid']} the UTM grid rectangle, **{a4['m_active']} hold at least one active cell** of {a4['run']} "
          f"(the two extra grid intersections, AOI26 Siete Aguas and AOI33 Sot de Chera, touch inactive corners).",
          f"- The run's cached EMS download (the truth snapshot) holds {len(a4['cached_aois'])} AOIs ({', '.join(a4['cached_aois'])}); AOI06 lies outside the domain (no active cell); S2 scores AOI01 and AOI14.",
          "- AOIs with active cells: " + ", ".join(f"AOI{int(x['number']):02d} {x['name']} ({x['active_cells_inside']} cells, {x['n_products']} product(s) {'/'.join(x['product_types'] or [])})" for x in a4["aois"] if x["active_cells_inside"] > 0) + ".", ""]
    # B4 / B5 / maps
    b4 = recs["b4_albufera"]; lag = b4["lagoon_wc80_component_excl_open_sea"]; ring = b4["margin_ring_3_cells"]
    L += [f"### B4 — Albufera lagoon (F7) {tag('b4_albufera')}", "",
          f"- Lagoon = the 4-connected WorldCover-80 component at the lagoon centre ({b4['centre']['lonlat']}): **{lag['cells']} cells, {lag['km2']} km²**, all msk = 1 (active, not open sea), "
          f"all inside the AOI union, **all excluded from the evaluation universe** (class 80 at the cell centre; in-universe cells {lag['in_universe_cells']}); z_b {lag['zb_m']['min']:.1f}–{lag['zb_m']['max']:.1f} m; "
          f"modelled h_max there: max {lag['hmax_active']['max_m']:.2f} m, median {lag['hmax_active']['median_m']:.2f} m, {lag['hmax_active']['cells_gt_0p10']} cells > 0.10 m. Had they been inside, "
          f"{lag['would_be_false_alarm_cells']} cells would be false alarms = {lag['would_be_share_of_record_FP_pct']} % of the record's {b4['record_fp_cells']} FP cells (EMS maps {lag['ems_observed_cells']} of them as flooded).",
          f"- Margin ring (3 cells around the lagoon): {ring['cells']} cells, WorldCover classes {ring['worldcover_classes']}; {ring['in_universe_cells']} inside the universe, {ring['wet_in_universe_cells']} wet, "
          f"{ring['false_alarm_cells']} false alarms = {ring['share_of_record_FP_pct']} % of the record's FP.",
          f"- Verdict: {b4['verdict']} → F7 re-exported with the exclusion mask above the depth layer (`r6_figures.EXCL_ON_TOP`).", ""]
    mp = recs["b_maps_wet_in_excluded"]["maps"]
    L += [f"- Depth drawn over excluded cells in the other maps {tag('b_maps_wet_in_excluded')}: " + "; ".join(f"{k} {v['event']} {v['wet_cells_in_excluded']} cells ({v['km2']} km², {v['share_of_wet_pct']} % of the wet cells)" for k, v in mp.items()) + " — left as drawn (decision for the author).", ""]
    b5 = recs["b5_emilia_south"]; s5 = b5["summary"]; cells = b5["southern_wet_cells"]
    big = sum(1 for c in cells if c["component_cells"] > 1000)
    L += [f"### B5 — Emilia-Romagna southern edge (F8) {tag('b5_emilia_south')}", "",
          f"- Rows 0–4 (y ascending, row 0 = southern boundary): **{s5['wet_cells']} cells with h_max > 0.10 m** ({s5['wet_per_row']} per row), **none inside an AOI**, none EMS-observed; row 0 holds "
          f"{s5['row0_msk1']} closed-boundary cells (msk = 1), {s5['row0_msk2']} water-level cells, and **{s5['row0_wet_closed']} wet cells touch the closed boundary**; depth up to {s5['hmax_max_m']:.2f} m; "
          f"z_b {min(c['zb_m'] for c in cells):.0f}–{max(c['zb_m'] for c in cells):.0f} m; nearest inflow source {min(c['nearest_source_m'] for c in cells) / 1e3:.1f} km away.",
          f"- {big} of the {len(cells)} cells belong to the domain-wide channel component (rows 0–{max(c['component_rows'][1] for c in cells)}), the rest to small valley-bottom components of 10–40 cells cut by the domain edge: "
          "Apennine channels whose upstream part lies outside the domain (closed boundary, no inflow prescribed there). Model output, not a plotting artefact → no re-export.", ""]
    # C
    cb = recs["crete_tier1_diagnostics_baseline"]["runs"]["crete_baseline"]
    L += ["### C — supplement rows", "",
          "- S1: 16 baseline rows added (pineios_baseline_gridmatched, mandra_baseline, strymonas_baseline, crete_baseline × 4 thresholds) from `phase4/cross_event_v14_v142.json` baseline_v14.sweep; "
          "S3: 4 baseline rows (fuzzy r = 0–3, one-sided, buffer, time-matched); Crete baseline buffer/time-matched on the tier-1 block from "
          f"{tag('crete_tier1_diagnostics_baseline')}: buffer −20 / 0 / +20 m CSI {cb['truth_buffer']['-20']['csi']:.3f} / {cb['truth_buffer']['0']['csi']:.3f} / {cb['truth_buffer']['20']['csi']:.3f}; "
          f"time-matched full / earliest / latest {cb['time_matched']['full']['csi']:.3f} / {cb['time_matched']['to_earliest']['csi']:.3f} / {cb['time_matched']['to_latest']['csi']:.3f}.",
          "- S2: the Strymonas baseline per-area rows 01–04 were already present (CSI 0.207/0.410, 0.124/0.357, 0.333/0.365, 0.358/0.455); unchanged.",
          "- S4: the Strymonas lead-in row relabelled '7-day lead-in simulated (10 d before the event day; canonical 3 d)' (from the two configs' windows).",
          "- S11 (new; supplement numbering S10): the Manning lookup, 11 WorldCover classes from `skill/manning_lookup.csv` (built-up 0.012; copies in all six run directories byte-identical). The file carries no per-class source.", ""]
    # D
    lk = recs["lookups"]
    r3 = lk["D3_rombeek2025"]; q = r3["quotes"]
    L += [f"### D — sources {tag('lookups')}", "",
          f"- D3 Rombeek et al. 2025 (HESS 29, 6715–6733): Table 1 (p. 6718) `{q['table1_row_ID4']['quote']}` (gauged Poyo catchment ID4 = 182 km²); Fig. 6a legend (p. 6723) `{q['fig6a_legend_areas_visual']['quote']}`; "
          f"§4.3 (p. 6723) `{q['catchment4_164mm']['quote']}`. {r3['reading']} {r3['figure_reading_visual']}",
          f"- D4 Bernhofen et al. 2018: `{recs['lookups']['D4_bernhofen2018']['quotes']['abstract']['quote']}`; results `{recs['lookups']['D4_bernhofen2018']['quotes']['results']['quote']}`; no median stated. "
          f"Trigg et al. 2016: `{recs['lookups']['D4_trigg2016']['quotes']['mai_kappa']['quote']}` and `{recs['lookups']['D4_trigg2016']['quotes']['abstract']['quote'][:70]}…` (model agreement, no CSI). "
          f"Hocini et al. 2021 (p. 2986): `{recs['lookups']['D4_hocini2021']['quotes']['section4_1']['quote']}`; La Redorte (p. 2987) 69 / 63 / 35 %. "
          "Wing et al. 2017: body not retrievable (Wiley and Bristol PDF 403); abstract: Hit Rate 86 % vs FEMA, 92 % vs USGS (100-year). "
          "**The §4.7 ranges ('Bernhofen 0.10–0.36, median ≈ 0.22', 'Trigg 0.10–0.35', 'Hocini 0.42–0.62') and the F10 band constants of fig_skill_sweeps_v14.py are not what these articles state** — reported, not changed (B1 says nothing else changes in F10).",
          f"- D5 Schumann et al. 2016: publisher page not readable (403); Bristol record `{lk['D5_schumann2016']['bristol_record']['pages_field']['quote']}` — not added to refs.bib.",
          f"- D6 Ross et al. 2018: Crossref {lk['D6_ross2018']['crossref']['container']} {lk['D6_ross2018']['crossref']['volume']}, article {lk['D6_ross2018']['crossref']['article_number']} ({lk['D6_ross2018']['crossref']['issued']}), title '{lk['D6_ross2018']['crossref']['title']}' — not added pending the author.",
          "- D1 Diakakis et al. 2019 / Varlas et al. 2019: neither full text retrievable by automated access (Elsevier paywall; mdpi.com 403 for fetcher and curl; no open mirror listed by OpenAlex/OpenAIRE/Semantic Scholar) — catchment areas and the Pateras wildfire not verified.",
          "- D2 Emilia-Romagna 2023: " + lk["D2_emilia_romagna_2023"]["summary"]["(a) >500-year return periods, Senio/Lamone/Montone"] + ". Rivers: " + lk["D2_emilia_romagna_2023"]["summary"]["(b) >20 rivers"] + ". Fatalities: " + lk["D2_emilia_romagna_2023"]["summary"]["(c) fatalities"] + ".",
          "- D7 Valencia anchor ledger: " + " → ".join(f"{e['anchor_mm'] or 'raw'} ({e['when'][:10]}; {e['score_computed'].split(';')[0]})" for e in lk["D7_valencia_anchor_ledger"]["entries"]) + ". " + lk["D7_valencia_anchor_ledger"]["reading"], ""]
    return "\n".join(L) + "\n"


def main() -> int:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", required=True, type=Path)
    ap.add_argument("--print", action="store_true")
    a = ap.parse_args()
    block = render(a.repo)
    if a.print:
        print(block); return 0
    p = a.repo / "docs" / "AUDIT.md"
    txt = p.read_text(encoding="utf-8")
    if "## CODE-19 (" in txt:
        raise SystemExit("docs/AUDIT.md already has a CODE-19 block")
    p.write_text(txt.rstrip("\n") + "\n\n" + block, encoding="utf-8")
    print(f"appended {block.count(chr(10))} lines to docs/AUDIT.md")
    return 0


if __name__ == "__main__":
    sys.exit(main())
